function getDownloadedDateTime() {
  const now = new Date();
  const pad = (value) => String(value).padStart(2, "0");

  return `${pad(now.getDate())}/${pad(now.getMonth() + 1)}/${now.getFullYear()} ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;
}

function buildIdbiSummary(statementTransactions) {
  const debitTransactions = statementTransactions.filter(
    (transaction) => transaction.type === "Dr",
  );
  const creditTransactions = statementTransactions.filter(
    (transaction) => transaction.type === "Cr",
  );

  const totalDebits = debitTransactions
    .reduce(
      (sum, transaction) => sum + Number.parseFloat(transaction.amount || 0),
      0,
    )
    .toFixed(2);

  const totalCredits = creditTransactions
    .reduce(
      (sum, transaction) => sum + Number.parseFloat(transaction.amount || 0),
      0,
    )
    .toFixed(2);

  return {
    drCount: debitTransactions.length,
    crCount: creditTransactions.length,
    totalDebits,
    totalCredits,
  };
}

function parseDateInput(dateStr = "") {
  const trimmed = dateStr.trim();

  if (!trimmed) {
    return null;
  }

  if (trimmed.includes("/")) {
    const [day, month, year] = trimmed.split("/").map(Number);

    if (!day || !month || !year) {
      return null;
    }

    return new Date(year, month - 1, day, 0, 0, 0, 0);
  }

  if (trimmed.includes("-")) {
    const [first, second, third] = trimmed.split("-");

    if (/^\d+$/.test(second)) {
      const day = Number(first);
      const month = Number(second);
      const year = Number(third);

      if (!day || !month || !year) {
        return null;
      }

      return new Date(year, month - 1, day, 0, 0, 0, 0);
    }

    const parsedDate = new Date(trimmed);

    if (Number.isNaN(parsedDate.getTime())) {
      return null;
    }

    parsedDate.setHours(0, 0, 0, 0);

    return parsedDate;
  }

  const parsedDate = new Date(trimmed);

  if (Number.isNaN(parsedDate.getTime())) {
    return null;
  }

  parsedDate.setHours(0, 0, 0, 0);

  return parsedDate;
}

function parseTransactionDateTime(dateStr = "") {
  const [datePart, timePart = "00:00:00"] = dateStr.trim().split(" ");
  const [day, month, year] = datePart.split("/").map(Number);
  const [hour, minute, second] = timePart.split(":").map(Number);

  return new Date(year, month - 1, day, hour, minute, second);
}

function formatSlashDate(date) {
  const pad = (value) => String(value).padStart(2, "0");

  return `${pad(date.getDate())}/${pad(date.getMonth() + 1)}/${date.getFullYear()}`;
}

function getEndOfDay(date) {
  const endOfDay = new Date(date);
  endOfDay.setHours(23, 59, 59, 999);
  return endOfDay;
}

function getDateRanges(fromDate, toDate) {
  const endDate = new Date(toDate);
  endDate.setHours(23, 59, 59, 999);

  const ranges = [];
  let currentStart = new Date(fromDate);
  currentStart.setHours(0, 0, 0, 0);

  while (currentStart <= endDate) {
    const tentativeEnd = new Date(currentStart);
    tentativeEnd.setFullYear(tentativeEnd.getFullYear() + 1);
    tentativeEnd.setDate(tentativeEnd.getDate() - 1);
    tentativeEnd.setHours(0, 0, 0, 0);

    const currentEnd =
      tentativeEnd > endDate ? new Date(endDate) : tentativeEnd;

    ranges.push({
      from: new Date(currentStart),
      to: currentEnd,
    });

    const nextStart = new Date(currentEnd);
    nextStart.setDate(nextStart.getDate() + 1);
    nextStart.setHours(0, 0, 0, 0);
    currentStart = nextStart;
  }

  return ranges;
}

function sanitizeFileName(value = "statement") {
  return (
    value.replace(/[^a-z0-9]+/gi, "-").replace(/^-+|-+$/g, "") || "statement"
  );
}

