async function createIdbiStatementPdf(accountInfoPayload, transactionList) {
  return new Promise((resolve, reject) => {
    const fakeRes = {
      setHeader() {},
      send(pdfBuffer) {
        resolve(pdfBuffer);
      },
      status(statusCode) {
        this.statusCode = statusCode;
        return this;
      },
      json(payload) {
        reject(
          new Error(
            payload?.error ||
              `Failed to generate statement PDF (${this.statusCode || 500})`,
          ),
        );
      },
    };

    // let isFirstCall = true;

    // const delay = isFirstCall ? 0 : Math.floor(Math.random() * 6000) + 10000;

    // isFirstCall = false;

    // setTimeout(() => {
    Promise.resolve(
      generateIdbiStatement(
        {
          body: {
            accountInfo: accountInfoPayload,
            transactions: transactionList,
          },
        },
        fakeRes,
      ),
    ).catch(reject);
    // }, delay);
  });
}

